 if($('order-category'))$('order-category').onchange=()=>{$('order-sku').innerHTML=options(CATALOG.filter(c=>!c.legacy&&!c.providerOnly&&c.category===$('order-category').value).map(c=>[c.id,`${c.name} · $${c.price.toLocaleString()}${c.weight?` · ${c.weight} kg`:''}`]));procurementSpec();};on('order-submit',()=>send({type:'order',sku:$('order-sku').value,quantity:+$('order-quantity').value,length:+$('order-length').value,emergency:$('order-emergency').checked}));
