 on('grab-item',async()=>{selected=$('stock-item').value;const out=await send({type:'grab',id:selected});if(out.startsWith('Picked up')||out.startsWith('Released')){kit.equip(0);close();}});on('install-rails',()=>send({type:'rails',id:$('stock-item').value,rack:$('install-rack').value,unit:+$('install-unit').value,units:+$('install-units').value}));on('mount-item',()=>send({type:'mount',id:$('stock-item').value,rack:$('install-rack').value,unit:+$('install-unit').value}));on('install-rack-button',()=>{selected=$('stock-item').value;notify('Pick up the rack, aim at a floor bay, then E');close();});on('insert-optic',()=>send({type:'optic',id:$('stock-item').value,node:$('service-device').value,port:+$('service-port').value}));on('replace-part',()=>send({type:'repair',id:$('stock-item').value,node:$('service-device').value}));on('power-connect',()=>send({type:'power',id:$('stock-item').value,node:$('service-device').value,psu:+$('psu-index').value,feed:$('pdu-feed').value||null}));on('power-toggle',()=>send({type:'boot',node:$('service-device').value}));on('equip-patch',async()=>{selected=$('stock-item').value;if(CATALOG.find(c=>c.id===ops.game.stock.find(s=>s.id===selected)?.sku)?.type!=='cable'){note('Select a data cable first');return;}const picked=await send({type:'grab',id:selected});if(!picked.startsWith('Picked up'))return;firstPort=null;kit.equip(0);close();enter();showEvent('DATA CABLE EQUIPPED','Aim at a free data port and press E to connect end A.');});
