 function setRole(value){if(!['field','operations'].includes(value))return;role=value;document.body.dataset.engineerRole=value;lan.setRole(value);$('role-wheel').hidden=true;$('engineer-role').textContent=value==='field'?'FIELD':'OPS';notify((value==='field'?'FIELD ENGINEER':'OPERATIONS ENGINEER')+' · all capabilities');}
