 function selectedRackAction(rack,unit){const s=heldItem(),c=CATALOG.find(c=>c.id===s?.sku);if(!s?.holders.includes(actor())||!c||!Number.isInteger(unit))return null;const r=racks.find(r=>r.id===rack);if(!r)return null;const units=c.type==='rail'?(CATALOG.find(c=>c.id===s.forSku)?.units||task()?.units||2):c.units;if(!units||units>42||unit+units-1>42)return null;if(ops.available().some(n=>!n.controller&&n.rack===rack&&n.unit<unit+units&&n.unit+n.units>unit))return null;const overlap=ops.game.rails.filter(x=>x.rack===rack&&x.unit<unit+units&&x.unit+x.units>unit);if(c.type==='rail'){if(overlap.length)return null;return {type:'rails',id:s.id,rack,unit,units};}if(['server','switch','san','storage','gpu','firewall','isp'].includes(c.type)){if(overlap.some(x=>x.used||x.unit!==unit||x.units!==units))return null;if(!overlap.length&&!ops.game.stock.some(x=>x.sku==='rail'&&!x.holders.length))return null;return {type:'mount',id:s.id,rack,unit};}return null;}
