  if(aim?.port?.service){const p=aim.port,n=aim.node,want=p.medium==='Console'?1:2;if(held)return bad('Hands full','G puts '+(c?.name||'it')+' down first');if(kit.slot===want)return 'E · Plug '+(want===1?'console cable':'service Ethernet')+' into '+portName(n,p);if(!(kit.assignedTools||[]).includes(want))return n.id+' '+p.name+' · equip the '+(want===1?'console cable':'service Ethernet lead')+' first (J → Laptop tab), then '+want+' and E';return n.id+' '+p.name+' · press '+want+' for the '+(want===1?'console cable':'service Ethernet lead')+', then E';}
