  if(aim?.delivery){const o=ops.game.orders.find(o=>o.id===aim.delivery);if(held)return bad('Hands full','G puts it down first');return o?.opened?'E · Take an item out of the '+name(o.sku)+' box':'E · Open the delivery box ('+(o?o.quantity+' × '+name(o.sku):'')+')';}
