  if(c?.type==='optic'&&aim?.port){const p=aim.port,why=opticFitError(p,c.id);if(why)return bad(why);if(p.optic)return bad(p.name+' already has an optic','R removes it (hands empty)');return c.speed===p.speed&&c.medium===p.medium?'E · Insert '+c.name+' into '+portName(aim.node,p):bad(c.name+' does not match '+p.name+' ('+p.speed+'G '+(p.medium==='Fibre Channel'?'FC':'Ethernet')+')','use a '+p.speed+'G optic');}
